// ─── Icon ───────────────────────────────────────────────────────────────────

export const Icon: Story = {
  args: {
    variant: 'icon',
    icon: 'search',
    label: 'Search',
    size: 'md',
  },
};

export const IconSmall: Story = {
  name: 'Icon — Small',
  args: {
    variant: 'icon',
    icon: 'search',
